#[derive(Debug, PartialEq, Eq)]
struct RightHeadSeq(Vec<(RightHead, usize)>);

impl RightHeadSeq {
    fn new() -> Self {
        Self(Vec::new())
    }

    fn pop(&mut self) -> Option<RightHead> {
        loop {
            if let Some((rhead0, n0)) = self.0.first() {
                if *n0 == 0 {
                    self.0.remove(0);
                    continue;
                } else {
                    let out = *rhead0;
                    if *n0 == 1 {
                        self.0.remove(0);
                    }
                    return Some(out);
                }
            } else {
                return None;
            }
        }
    }

    fn push_head(&mut self, rhead: RightHead) {
        if let Some((rhead0, n0)) = self.0.last_mut()
            && *rhead0 == rhead
        {
            *n0 += 1;
        } else {
            self.0.push((rhead, 1));
        }
    }

    fn append_seq(&mut self, seq: &RightHeadSeq) {
        if let Some((rhead0, n0)) = self.0.last_mut()
            && let Some((rhead1, n1)) = seq.0.first()
            && rhead0 == rhead1
        {
            *n0 += n1;
            self.0.extend_from_slice(&seq.0[1..]);
        } else {
            self.0.extend_from_slice(seq.0.as_slice());
        }
    }
}

impl fmt::Display for RightHeadSeq {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut iter = self.0.iter().rev();
        if let Some((rhead, n)) = iter.next() {
            if *n == 1 {
                write!(f, "{}", rhead)?;
            } else {
                write!(f, "{}^{}", rhead, n)?;
            }
        }
        while let Some((rhead, n)) = iter.next() {
            write!(f, " ")?;
            if *n == 1 {
                write!(f, "{}", rhead)?;
            } else {
                write!(f, "{}^{}", rhead, n)?;
            }
        }
        Ok(())
    }
}

#[derive(Debug, PartialEq, Eq)]
enum SimInfo {
    Regular,
    LeftLong { n_left_heads: usize },
    RightLong { right_heads: RightHeadSeq },
}

impl BlockSimulator {
    fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L],
            right_tape: vec![R0, Run(Y, 5)],
            state: HigherState::Right,
            base_steps: 84,
            self_steps: 0,
            sim_info: SimInfo::Regular,
        }
    }

    /// left_tape should not have L
    fn new_left_long(left_tape: Vec<BlockSymbol>) -> Self {
        Self {
            left_tape,
            right_tape: Vec::new(),
            state: HigherState::Left,
            base_steps: 0,
            self_steps: 0,
            sim_info: SimInfo::LeftLong { n_left_heads: 0 },
        }
    }

    fn new_right_long(state: HigherState, right_tape: Vec<BlockSymbol>) -> Self {
        Self {
            left_tape: Vec::new(),
            right_tape,
            state,
            base_steps: 0,
            self_steps: 0,
            sim_info: SimInfo::RightLong {
                right_heads: RightHeadSeq::new(),
            },
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if let SimInfo::LeftLong { n_left_heads } = &mut self.sim_info
            && self.left_tape.is_empty()
            && self.state == HigherState::Left
        {
            *n_left_heads += 1;
            self.state = HigherState::Right;
            self.self_steps += 1;
            return Ok(());
        }

        if matches!(self.sim_info, SimInfo::LeftLong { n_left_heads: _ })
            && self.right_tape.is_empty()
        {
            use HigherState::*;
            match self.state {
                Right => return Err(SimError::LongSimCompleted),
                RightWide => return Err(SimError::RightInverseHeadMismatch),
                Left => (),
            }
        }

        if let SimInfo::RightLong { right_heads } = &mut self.sim_info
            && self.right_tape.is_empty()
            && let Some(rhead) = self.state.try_to_right_head()
        {
            right_heads.push_head(rhead);
            self.state = HigherState::Left;
            self.self_steps += 1;
            return Ok(());
        }

        if matches!(self.sim_info, SimInfo::RightLong { right_heads: _ })
            && self.left_tape.is_empty()
            && self.state == HigherState::Left
        {
            return Err(SimError::LongSimCompleted);
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }
}

fn apply_h_head(
    left_tape: Vec<BlockSymbol>,
    verbose: bool,
    print_left_end: bool,
) -> Option<(usize, Vec<BlockSymbol>)> {
    let mut sim = BlockSimulator::new_left_long(left_tape);
    loop {
        match sim.step() {
            Ok(_) => {
                if verbose
                    || (print_left_end
                        && sim.left_tape.is_empty()
                        && sim.state == HigherState::Right)
                {
                    println!("{sim}")
                }
            }
            Err(SimError::Halted | SimError::UndefinedTransition) => unreachable!(),
            Err(SimError::LongSimCompleted) => {
                let SimInfo::LeftLong { n_left_heads } = sim.sim_info else {
                    unreachable!()
                };
                return Some((n_left_heads, sim.left_tape));
            }
            Err(SimError::RightInverseHeadMismatch) => {
                eprintln!("head mismatch {sim}");
                return None;
            }
        }
    }
}

fn apply_right_head(
    rhead: RightHead,
    right_tape: Vec<BlockSymbol>,
    verbose: bool,
) -> Result<(RightHeadSeq, Vec<BlockSymbol>), SimError> {
    let mut sim = BlockSimulator::new_right_long(rhead.to_higher_state(), right_tape);
    loop {
        match sim.step() {
            Ok(_) => {
                if verbose {
                    println!("{sim}")
                }
            }
            Err(SimError::LongSimCompleted) => {
                let SimInfo::RightLong { right_heads } = sim.sim_info else {
                    unreachable!()
                };
                return Ok((right_heads, sim.right_tape));
            }
            Err(SimError::UndefinedTransition) => return Err(SimError::UndefinedTransition),
            _ => unreachable!(),
        }
    }
}

fn apply_f_head(
    right_tape: Vec<BlockSymbol>,
    verbose: bool,
) -> Result<(RightHeadSeq, Vec<BlockSymbol>), SimError> {
    apply_right_head(RightHead::F, right_tape, verbose)
}

