fn parse_left_tape(s: &str) -> Option<Vec<BlockSymbol>> {
    use BlockSymbol::*;
    let mut out = Vec::new();
    for p in s.split(" ") {
        if p.contains("^") {
            let (symb, exp) = p.split_once("^").unwrap();
            if symb != "X" {
                eprintln!("oh no {symb}");
                return None;
            }
            let n = exp.parse::<Exp>().unwrap();
            out.push(Run(RunSymbolType::X, n));
        } else {
            let symb = match p {
                "P" => P,
                "D" => D,
                "X" => Run(RunSymbolType::X, 1),
                _ => {
                    eprintln!("oh no {p}");
                    return None;
                }
            };
            out.push(symb);
        }
    }
    Some(out)
}

fn parse_right_tape(s: &str) -> Option<Vec<BlockSymbol>> {
    use BlockSymbol::*;
    let mut out = Vec::new();
    for p in s.split(" ") {
        if p.contains("^") {
            let (symb, exp) = p.split_once("^").unwrap();
            if symb != "Y" {
                eprintln!("oh no {symb}");
                return None;
            }
            let n = exp.parse::<Exp>().unwrap();
            out.push(Run(RunSymbolType::Y, n));
        } else {
            let symb = match p {
                "Q" => Q,
                "Y" => Run(RunSymbolType::Y, 1),
                _ => {
                    eprintln!("oh no {p}");
                    return None;
                }
            };
            out.push(symb);
        }
    }
    out.reverse();
    Some(out)
}

fn is_XPX(v: &Vec<BlockSymbol>) -> bool {
    use BlockSymbol::{P, Run};
    use RunSymbolType::X;
    matches!(v.as_slice(), [Run(X, _), P, Run(X, _)])
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StepType {
    /// double the infinite cycle
    Double,
    /// propagate the h heads leftwards through the tape
    Prop,
}

#[derive(Clone)]
struct LongSimState {
    n_double: usize,
    n_prop: usize,
    left_exp: Exp,
    tape: Vec<BlockSymbol>,
    h_exp_right: usize,
    next_step: StepType,
}

impl LongSimState {
    fn init() -> Self {
        Self {
            n_double: 0,
            n_prop: 0,
            left_exp: 6,
            tape: parse_left_tape("X^2 P X^2 P X^6").unwrap(),
            h_exp_right: 2,
            next_step: StepType::Double,
        }
    }

    fn get_next_state(&self) -> Option<Self> {
        match &self.next_step {
            StepType::Double => {
                // L X^m (tape h^n tape h^n)^inf
                let mut out_tape = self.tape.clone();
                let mut n_h_out = 0;
                for _ in 0..self.h_exp_right {
                    if is_XPX(&out_tape) {
                        return None;
                    }
                    if let Some((n_heads, out_tape0)) = apply_h_head(out_tape, false, false) {
                        out_tape = out_tape0;
                        n_h_out += n_heads;
                    } else {
                        return None;
                    }
                }
                // L X^m (h^n_out out_tape tape h^n)^inf
                use BlockSymbol::Run;
                use RunSymbolType::X;
                if let Some(Run(X, n0)) = out_tape.last_mut()
                    && let Some(Run(X, n1)) = self.tape.first()
                {
                    *n0 += n1;
                    out_tape.extend_from_slice(&self.tape[1..]);
                } else {
                    out_tape.extend_from_slice(&self.tape.as_slice());
                }
                // L X^m (h^n_out out_tape h^n)^inf
                for _ in 0..self.h_exp_right {
                    if is_XPX(&out_tape) {
                        return None;
                    }
                    if let Some((n_heads, out_tape0)) = apply_h_head(out_tape, false, false) {
                        out_tape = out_tape0;
                        n_h_out += n_heads;
                    } else {
                        return None;
                    }
                }
                // L X^m (h^n tape)^inf -> L X^m+n (tape h^n)^inf
                Some(Self {
                    n_double: self.n_double + 1,
                    n_prop: 0,
                    left_exp: self.left_exp + n_h_out as Exp,
                    tape: out_tape,
                    h_exp_right: n_h_out,
                    next_step: StepType::Prop,
                })
            }
            StepType::Prop => {
                let mut tape = self.tape.clone();
                let mut n_h_out = 0;
                for _ in 0..self.h_exp_right {
                    if is_XPX(&tape) {
                        return None;
                    }
                    if let Some((n_heads, out_tape)) = apply_h_head(tape, false, false) {
                        tape = out_tape;
                        n_h_out += n_heads;
                    } else {
                        return None;
                    }
                }
                // L X^m (h^n tape)^inf -> L X^m+n (tape h^n)^inf
                Some(Self {
                    n_double: self.n_double,
                    n_prop: self.n_prop + 1,
                    left_exp: self.left_exp + n_h_out as Exp,
                    tape,
                    h_exp_right: n_h_out,
                    next_step: StepType::Prop,
                })
            }
        }
    }

    fn apply_next_step_heuristic(&mut self) {
        use BlockSymbol::{P, Run};
        use RunSymbolType::X;
        if matches!(
            self.tape.as_slice(),
            [Run(X, _), P, Run(X, 2), P, Run(X, _)]
        ) {
            self.next_step = StepType::Double;
        } else {
            self.next_step = StepType::Prop;
        }
    }

    /// seems like all the tapes can reach X^a P X^2 P X^b ?
    /// so just match on that pattern and double in that case
    fn go_to_next_state(&mut self, print_left_end: bool) {
        match &self.next_step {
            StepType::Double => {
                // L X^m (tape h^n tape h^n)^inf
                let mut out_tape = self.tape.clone();
                let mut n_h_out = 0;
                for _ in 0..self.h_exp_right {
                    if is_XPX(&out_tape) {
                        panic!("is_XPX");
                    }
                    let (n_heads, out_tape0) =
                        apply_h_head(out_tape, false, print_left_end).unwrap();
                    out_tape = out_tape0;
                    n_h_out += n_heads;
                }
                // L X^m (h^n_out out_tape tape h^n)^inf
                use BlockSymbol::Run;
                use RunSymbolType::X;
                if let Some(Run(X, n0)) = out_tape.last_mut()
                    && let Some(Run(X, n1)) = self.tape.first()
                {
                    *n0 += n1;
                    out_tape.extend_from_slice(&self.tape[1..]);
                } else {
                    out_tape.extend_from_slice(&self.tape.as_slice());
                }
                // L X^m+n_out (out_tape tape h^n+n_out)^inf
                self.n_double += 1;
                self.n_prop = 0;
                self.left_exp += n_h_out as Exp;
                self.tape = out_tape;
                self.h_exp_right += n_h_out;
                self.apply_next_step_heuristic();
            }
            StepType::Prop => {
                let tape = std::mem::take(&mut self.tape);
                if is_XPX(&tape) {
                    panic!("is_XPX");
                }
                let (n_heads, out_tape) = apply_h_head(tape, false, print_left_end).unwrap();
                self.h_exp_right -= 1;
                self.n_prop += 1;
                self.left_exp += n_heads as Exp;
                self.tape = out_tape;
                self.h_exp_right += n_heads;
                self.apply_next_step_heuristic();
            }
        }
    }
}

fn run_long_sim(n_steps: usize) {
    let mut k = 0;
    let mut backtrack = false;
    let mut sim_record: Vec<LongSimState> = vec![LongSimState::init()];

    loop {
        if backtrack {
            println!("backtracking");
            match sim_record.last().unwrap().next_step {
                StepType::Double => {
                    sim_record.pop();
                }
                StepType::Prop => {
                    sim_record.last_mut().unwrap().next_step = StepType::Double;
                    backtrack = false;
                }
            }
        } else {
            let last_state = sim_record.last().unwrap();
            let step_type = last_state.next_step;
            if let Some(next_state) = last_state.get_next_state() {
                sim_record.push(next_state);
            } else {
                match step_type {
                    StepType::Double => {
                        sim_record.pop();
                        backtrack = true;
                    }
                    StepType::Prop => sim_record.last_mut().unwrap().next_step = StepType::Double,
                }
            }
        }
        k += 1;
        // println!("{k} | {}", sim_record.last().unwrap());
        println!(
            "{k} | {}, {}",
            sim_record.len(),
            sim_record.last().unwrap().tape.len()
        );
        if k >= n_steps {
            for state in sim_record {
                if state.next_step == StepType::Double {
                    println!("{state}");
                }
            }
            return;
        }
    }
}

fn run_long_sim_v2(n_steps: usize, verbose: bool, print_left_end: bool) {
    let mut sim_state = LongSimState::init();
    println!("{sim_state}");

    for k in 0..n_steps {
        sim_state.go_to_next_state(print_left_end);

        if verbose || sim_state.next_step == StepType::Double || sim_state.n_prop % 100000 == 0 {
            println!("{k} | {sim_state}");
        }
    }
}

impl fmt::Display for LongSimState {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        self.n_double.fmt(f)?;
        write!(f, ", ")?;
        self.n_prop.fmt(f)?;
        write!(f, ": L X^{} ({}", self.left_exp, DisplayTape(&self.tape))?;

        if self.h_exp_right > 0 {
            if self.h_exp_right == 1 {
                write!(f, "h")?;
            } else {
                write!(f, "h^{}", self.h_exp_right)?;
            }
        }
        write!(f, ")^inf {:?}", self.next_step)
    }
}

